class Calc {
    int sum(int a, int b) {
        return a + b;
    }
    long sum(long a, long b) {
        return a + b + 100;
    }
    int sum(int... a) {
        int s = 0;
        for (int x : a) s += x;
        return s + 1000;
    }
}
public class Main {
    public static void main(String[] args) {
        Calc c = new Calc();
        System.out.println(c.sum(1, 2));
        System.out.println(c.sum(1L, 2));
    }
}

