record User(String name, int age) {
    User {
        name = name.trim();
        if (age < 0) age = 0;
    }
    String label() {
        return name + ":" + age;
    }
}
public class Main {
    public static void main(String[] args) {
        var u = new User(" Ada ", -1);
        System.out.println(u.name());
        System.out.println(u.label());
    }
}

