class Box {
    int x = 1;
    void run() {
        int x = 2;
        {
            int y = x + this.x;
            System.out.print(y + " ");
        }
        System.out.println(x);
    }
}
public class Main {
    public static void main(String[] args) {
        new Box().run();
    }
}

